<div class="ms-page-head"><div><h1>Sales & invoices</h1><p>Completed sales, payment status, outstanding dues and customer invoices.</p></div><?php if(auth()->user()->can('sales.create')): ?><a class="ms-btn ms-btn-primary" href="<?= site_url('sales/new') ?>">+ New Sale</a><?php endif; ?></div><div class="ms-search ms-spacer-bottom"><input class="ms-input" data-table-filter="#salesTable" placeholder="Search invoice or customer"></div>
<div class="ms-table-scroll"><table class="ms-table" id="salesTable"><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th>Total</th><th>Paid</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= esc($r['invoice_no']) ?></strong></td><td><?= esc($r['customer_name']) ?><br><span class="ms-muted"><?= esc($r['customer_phone']) ?></span></td><td><?= esc($r['sale_date']) ?></td><td>₹<?= number_format((float)$r['grand_total'],2) ?></td><td>₹<?= number_format((float)$r['paid_amount'],2) ?></td><td><strong class="<?= (float)$r['due_amount']>0?'ms-text-danger':'' ?>">₹<?= number_format((float)$r['due_amount'],2) ?></strong></td><td><span class="ms-badge <?= $r['payment_status']==='paid'?'is-ok':($r['payment_status']==='partial'?'is-warn':'is-danger') ?>"><?= esc(ucfirst($r['payment_status'])) ?></span></td><td><a class="ms-btn ms-btn-secondary is-sm" href="<?= site_url('sales/'.$r['id'].'/invoice') ?>">Open Invoice</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="ms-empty ms-no-filter">No sales yet.</td></tr><?php endif; ?></tbody></table></div>
